        private Stream BuildCacheFile(byte[] fileContent = null, string filePath = null)
        {
            var key = string.Concat("FILE|", _assemblyFilePath);
            var obj = System.Web.HttpContext.Current.Cache[key];

            // nao existe no cache
            if (obj == null)
            {
                if (!string.IsNullOrEmpty(filePath))
                    fileContent = File.ReadAllBytes(filePath);
                
                // arquivo tem conteudo
                if (fileContent != null)
                {
                    // cache habilitado
                    if (System.Web.HttpContext.Current.IsDebuggingEnabled == false)
                    {
                        // adiciona no cache
                        System.Web.HttpContext.Current.Cache.Insert(key, fileContent,
                            null,
                            System.Web.Caching.Cache.NoAbsoluteExpiration,
                            System.Web.Caching.Cache.NoSlidingExpiration,
                            System.Web.Caching.CacheItemPriority.High,
                            null);
                    }

                    return new MemoryStream(fileContent, false);
                }
                else
                {
                    //throw new Exception("Null BuildCacheFile");
                    return null;
                }
            }

            return new MemoryStream(obj as byte[], false);
        }

        public override Stream Open()
