            }

            //Logger.InfoLinx("Log_Custom", "Open", string.Format("Arquivo relativo: {0}", _assemblyPath));

            //Linx.Internet.Application.Framework.Web.PluginConfig.EmbeddedResources

            string[] parts = _assemblyFilePath.Split("/".ToCharArray(), 4);

            //var CustomQueryString = System.Web.HttpContext.Current.Request.QueryString["custom"];
            //var CustomOff = (CustomQueryString != null && CustomQueryString.Equals("off", StringComparison.InvariantCultureIgnoreCase));

            if (System.Web.HttpContext.Current.Request.QueryStringExistsValue("custom", "off") == false && parts.Length > 2)
            {

                parts[2] = parts[2].Replace('/', '\\');
#if DEBUG
                if (parts.Length > 3)
                {
                    parts[3] = parts[3].Replace('/', '\\');
                    #region Recurso Original (Replace Embedded Resources)
                    //
                    // ~\[Views\Index.aspx]
                    //
                    var replaceViewPath = Path.Combine(HttpRuntime.AppDomainAppPath, parts[3]);
                    if (File.Exists(replaceViewPath))
                        // return File.Open(replaceViewPath, FileMode.Open, FileAccess.Read);
                        return this.BuildCacheFile(null, replaceViewPath);
                    #endregion
                }
#endif
                #region Recurso Original (Replace Embedded Resources) com refencia do modulo e versao
                //
                // ~\linx-internet-application\v1.0.0.0-debug\[Views\Index.aspx]
                //
                var replaceViewPath2 = Path.Combine(HttpRuntime.AppDomainAppPath, parts[1], parts[2], parts[3]);
