                #region Recurso Customizado (View, Js, Css)
                //
                // ~\_Custom\linx-internet-application\v1.0.0.0-debug\[Views\Index.aspx]
                //
                var customViewPath = Path.Combine(HttpRuntime.AppDomainAppPath, "_custom", parts[1], parts[2], parts[3]);

                if (File.Exists(customViewPath))
                    //return File.Open(customViewPath, FileMode.Open, FileAccess.Read);
                    return this.BuildCacheFile(null, customViewPath);

                #endregion


                #region Recurso Customizado Append / Footer (View, Js, Css)
                //
                // ~\_Custom\[NomeArea]\Pedido\Scripts\teste.js.header
                //
                var existsFileHeader = File.Exists(string.Concat(customViewPath, "_header"));
                var existsFileFooter = File.Exists(string.Concat(customViewPath, "_footer"));

                if (existsFileHeader || existsFileFooter)
                {
                    using (MemoryStream streamFull = new MemoryStream())
                    {
                        var streamEmbedded = new MemoryStream(PluginConfig.EmbeddedResources[_assemblyFileEmbeddedPath].Bytes, false);

                        // adiciona o arquivo .header no comeco do stream
                        if (existsFileHeader)
                        {
                            using (FileStream fileStream = File.Open(string.Concat(customViewPath, "_header"), FileMode.Open, FileAccess.Read))
                            {
                                byte[] block = new byte[fileStream.Length];
                                fileStream.Read(block, 0, block.Length);

                                streamFull.Write(block, 0, block.Length);
                            }
                        }

                        // adiciona o arquivo inteiro no meio do stream
                        byte[] blockEmbedded = PluginConfig.EmbeddedResources[_assemblyFileEmbeddedPath].Bytes;
                        streamFull.Write(blockEmbedded, 0, blockEmbedded.Length);

                        // adiciona o arquivo .footer no fim do stream
                        if (existsFileFooter)
                        {
                            using (FileStream fileStream = File.Open(string.Concat(customViewPath, "_footer"), FileMode.Open, FileAccess.Read))
                            {
                                byte[] block = new byte[fileStream.Length];
                                fileStream.Read(block, 0, block.Length);

                                streamFull.Write(block, 0, block.Length);
                            }
                        }

                        //return new MemoryStream(streamFull.ToArray(), false);
                        return this.BuildCacheFile(streamFull.ToArray());

                    }

                }
                #endregion
            }
