        public static List<string> PathRelativeResource(string virtualPath)
        {
            //Logger Logger = LogManager.GetLogger("Log_Custom");

            //Logger.InfoLinx("Log_Custom", "Custom", string.Format("Arquivo relativo: {0}", virtualPath));

            List<string> r = new List<string>();

            string[] parts = VirtualPathUtility.ToAppRelative(virtualPath).Split("/".ToCharArray(), 3);

            var replaceViewPath = Path.Combine(HttpRuntime.AppDomainAppPath, parts[1], parts[2].Replace('/', '\\'));

            //Logger.InfoLinx("Log_Custom", "Custom", string.Format("replaceViewPath : {0}", replaceViewPath));
            if (File.Exists(replaceViewPath))
            {
                r.Add(string.Concat("/", parts[1], "/", parts[2]));
            }

            string key = VirtualPathUtility.ToAppRelative(virtualPath).Replace('/', '.'); //.Replace("~", "~.shell.v1.0.0.0-debug");

            //if (!virtualPath.Contains("v1.0.0.0-debug"))
            //{
            //    key = key.Replace("~", "~.shell.v1.0.0.0-debug");
            //}

            var dicionarioArquivo = PluginConfig.EmbeddedResources[key];

            var customViewPath = Path.Combine(HttpRuntime.AppDomainAppPath, "_Custom", dicionarioArquivo.ModuleName, parts[1], parts[2].Replace('/', '\\'));

            //Logger.InfoLinx("Log_Custom", "Custom", string.Format("customViewPath : {0}", customViewPath));

            if (File.Exists(customViewPath) || File.Exists(string.Concat(customViewPath, "_header")) || File.Exists(string.Concat(customViewPath, "_footer")))
            {
                // adiciona a pasta a qual pertence o arquivo
                r.Add(string.Concat("/Custom/", dicionarioArquivo.ModuleName, "/", parts[1], "/",
                        parts[2].Replace(Path.GetFileName(virtualPath), string.Empty).Replace("/", string.Empty)));
            }

            return r;
        }

